*/

function samplingFunction(func, count, context) {
  let counter = 0;
  return function (...args) {
    context = this ?? context;
    if (++counter !== count) return;
    func.apply(context, args);
    counter = 0;
  }
}

function message() {
  console.log('Hello');
};

const sample = samplingFunction(message, 4);

