*/

let digitalRootUsingRecursion = (n) => {
    /*
        T.C - O(N*2)
        S.C - O(N)
    */
    let sum = 0;
    while (parseInt(n) > 0) {
        let temp = n % 10;
        sum = sum + temp;
        n = parseInt(n / 10);
    };
    if (sum < 10) {
        return sum;
    };
    return digitalRootUsingRecursion(sum);
};

