let testCase1 = {
    a: {
        b: (a, b, c) => a + b + c,
        c: (a, b, c) => a + b - c,
    },
    d: (a, b, c) => a - b - c
};

function piping(obj) {
    return function(...args) {
        for(let key in obj) {
            let val = obj[key];
            if(typeof val === "function") {
                obj[key] = val(...args);
            } else if (typeof val === "object"){
                obj[key] = piping(val)(...args);
            }
        }
        return obj;
    };
};

