// Promise.any Polyfill using .then().catch()
function promiseAnyPolyfillUsingThenCatch(promiseArray) {
  let errors = [];
  return new Promise((resolve, reject) => {
    promiseArray.forEach((promise, index) => {
      promise.then((result) => {
        resolve(result);
      }).catch((error) => {
        errors[index] = error;
        if (errors.length === promiseArray.length) {
